<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamGuestApplicationDTO; use Inc\Enums\Settings\TableName; class ExamGuestApplicationRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamGuestApplications->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamGuestApplicationDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamGuestApplicationDTO::fromArray( $row ) : null; } public function findBySessionAndKey( int $sessionId, string $requestKey ): ?ExamGuestApplicationDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE session_id = %d AND request_key = %s", $this->table, $sessionId, $requestKey ), ARRAY_A ); return $row ? ExamGuestApplicationDTO::fromArray( $row ) : null; } public function findHeldBySession( int $sessionId ): array { $rows = $this->wpdb->get_results( $this->wpdb->prepare( "SELECT * FROM %i WHERE session_id = %d AND is_held = 1", $this->table, $sessionId ), ARRAY_A ); return array_map( [ ExamGuestApplicationDTO::class, 'fromArray' ], $rows ?: [] ); } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
